// DecodeGetRequest returns a decoder for requests sent to the agents get
// endpoint.
func DecodeGetRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*agents.GetPayload, error) {
	return func(r *http.Request) (*agents.GetPayload, error) {
		var payload *agents.GetPayload
		var (
			id           string
			sessionToken *string
			err          error
		)
		id = r.URL.Query().Get("id")
		if id == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("id", "query string"))
		}
		err = goa.MergeErrors(err, goa.ValidateFormat("id", id, goa.FormatUUID))
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewGetPayload(id, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

